#include "domain/reedcrest.hpp"
#include "domain/thistletail.hpp"
#include "engine/native_population_registry.hpp"
#include "domain/hero_destination.hpp"
#include <iostream>
using namespace stalthos;
using namespace stalthos::fauna;
static void require(bool b,const char* why){if(!b)throw std::runtime_error(why);}
int main(){try{
 require(domain::playableSpecies("Reedcrest")==HeroSpecies::Reedcrest,"fourth real selected species");needs::NeedsCore own(HeroSpecies::Reedcrest);Lifecycle life(HeroSpecies::Reedcrest);require(own.species()==life.species(),"own real components");
 std::vector<HabitatSite> sites{{{0,2,0},false,true,{1}},{{4,2,0},false,false,{0,2}},{{8,2,0},true,false,{1}}};Population original(42,1001,sites,1);auto state=original.snapshot();auto& actor=state.actors[0];actor.species=HeroSpecies::Reedcrest;actor.calendarAge=100;actor.stage=LifeStage::Hatchling;actor.site=1;actor.target=0;actor.position={3,2,0};actor.activity=Activity::Travel;actor.hunger=.1;actor.thirst=.1;actor.fatigue=.1;original.restore(state);const auto id=actor.id;
 const Vec3 body{8,2,0};PeerCompanionship link;for(int i=0;i<3;++i)link.update(1,HeroSpecies::Reedcrest,body,true,.5,(i+1)*.5,original.actors());require(link.peer()==id && link.present(),"actual local calm conspecific pair learned");
 auto decision=domain::reedPeerDecision(body,true,false,false,false,&original.actors()[0]);require(decision.leader==domain::ReedLeader::Partner && bool(decision.heroTarget),"idle hero follows actual partner body");require(domain::reedPeerDecision(body,true,true,false,false,&original.actors()[0]).leader==domain::ReedLeader::Hero,"direct hero leads");require(domain::reedPeerDecision(body,true,false,true,false,&original.actors()[0]).leader==domain::ReedLeader::Hero,"existing destination wins");require(domain::reedPeerDecision(body,true,false,false,true,&original.actors()[0]).leader==domain::ReedLeader::Hero,"hero needs win");require(domain::reedPeerDecision({36,2,0},true,false,false,false,&original.actors()[0]).leader==domain::ReedLeader::None,"remote camera cannot guide body");
 Population follows=original,leads=original;BodyAwareness following{body,{},id,3,false,true},leading{body,{},id,3,true,true};follows.advance({1,1},false,following);leads.advance({1,1},false,leading);require(follows.actors()[0].position.x>3 && leads.actors()[0].position.x<3,"actual graph partner reverses toward leading hero or keeps independent lead");require(follows.actors()[0].calendarAge==101 && leads.actors()[0].calendarAge==101,"one lifecycle tick");auto check=follows.snapshot();follows.restore(check);require(follows.actors()[0].id==id,"reversed exact graph edge remains restore-valid");
 for(int i=0;i<20;++i)follows.advance({1,1},false,following);require(std::abs(follows.actors()[0].position.x-5)<1e-8,"actual in-flight partner waits3m without teleport");
 link.update(1,HeroSpecies::Reedcrest,{36,2,0},false,1,3,original.actors());require(link.peer()==id && !link.present(),"separation retains same identity");link.update(1,HeroSpecies::Reedcrest,body,false,1,4,original.actors());require(link.peer()==id && link.present(),"body reunion no new peer");
 auto urgentState=state;auto& thirsty=urgentState.actors[0];thirsty.site=0;thirsty.target=0;thirsty.position=sites[0].position;thirsty.activity=Activity::Drink;thirsty.thirst=.8;Population urgent=original;urgent.restore(urgentState);require(domain::reedPeerDecision({2,2,0},true,false,false,false,&urgent.actors()[0]).leader==domain::ReedLeader::None,"urgent partner takes own needs");
 ResourceLedgerDto ledger{{{100,ResourceKind::Creek,10,1},{200,ResourceKind::Shrub,10,1}},{{90,100,1},{91,200,1}}};std::uint64_t next=100;engine::NativePopulationRegistry host(urgent,ledger,{},{{0,100,sites[0].position},{2,200,sites[2].position}},next);const auto bindings=host.sessions();const auto before=host.snapshot();host.advance({1,1},true,BodyAwareness{{2,2,0},{},id,3,true,true});require(host.events().size()==1 && host.events()[0].actor==id && host.events()[0].resource==100,"bonded urgent partner actually drinks through shared registry despite nearby hero");require(host.snapshot().actors[0].thirst<.8 && host.snapshot().actors[0].calendarAge==101,"real relief once plus age once");require(host.sessions()==bindings && host.ledger().sessions[0].amount==1 && host.ledger().sessions[1].amount==1,"old bindings and full old history preserved");const auto after=host.snapshot();host.advanceDormant({2,3});require(host.snapshot().actors[0].position.x==after.actors[0].position.x && host.snapshot().actors[0].calendarAge==104,"dormant age only no phantom follow");
 std::vector<HabitatSite> directedSites{{{0,2,0},false,true,{1}},{{4,2,0},false,false,{2}},{{4,2,4},true,false,{0}}};Population directed(42,1001,directedSites,1);auto directedState=directed.snapshot();auto& directedActor=directedState.actors[0];directedActor.species=HeroSpecies::Reedcrest;directedActor.site=0;directedActor.target=1;directedActor.position={3,2,0};directedActor.activity=Activity::Travel;directedActor.hunger=.1;directedActor.thirst=.1;directedActor.fatigue=.1;directed.restore(directedState);directed.advance({.1,.1},false,BodyAwareness{{-4,2,0},{},directedActor.id,3,false,true});directed.restore(directed.snapshot());require(directed.snapshot().actors[0].site==0,"directed edge cannot invent reverse route");
 HeroSim hero;require(domain::HeroDestination::submit(hero,body,*decision.heroTarget,true),"hero existing contextual owner");domain::HeroDestination::update(hero,body,0,.1,true,true,true);require(!domain::HeroDestination::active(hero),"ordinary direct override");
 std::cout<<"REEDCREST_RECIPROCAL_OK learned real peer both directions supported reversal/wait needs contact history separation reunion once-only age\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
